export const recommendationHtml = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Recommendation Letter \u2014 Brian Maina Kuria</title>\n<style>\n  :root{\n    --paper:#FEFCE8; --ink:#2C2C2B; --ink2:#3d3b37;\n    --border:#c9c4a8; --red:#a3272c; --blue:#1d3f8f;\n    --sans:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;\n  }\n  *{box-sizing:border-box;}\n  body{\n    margin:0; background:#F0EFED; color:var(--ink);\n    font-family:var(--sans); font-size:15px; line-height:1.6;\n  }\n  .actions{\n    max-width:820px; margin:0 auto; padding:16px 40px 0;\n    display:flex; justify-content:flex-end;\n  }\n  .dl{\n    display:inline-flex; align-items:center; gap:8px;\n    min-height:44px; padding:0 20px; border-radius:8px;\n    background:var(--blue); color:#fff; font-size:14px; font-weight:600;\n    text-decoration:none; border:1px solid #16316f;\n  }\n  .dl:hover{background:#16316f;}\n  .dl svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;}\n\n  .sheet{\n    max-width:820px; margin:20px auto 64px; background:var(--paper);\n    border:1px solid var(--border); border-radius:4px;\n    padding:56px 64px 48px;\n    box-shadow:0 1px 2px rgba(0,0,0,.05),0 4px 14px rgba(0,0,0,.06);\n  }\n\n  header{text-align:center; margin-bottom:28px;}\n  .crest{width:104px; height:auto; margin:0 auto 10px; display:block;}\n  .republic{margin:0 0 10px; font-size:13px; letter-spacing:.04em; color:var(--ink2);}\n  .office{margin:0; font-size:17px; font-weight:700; color:var(--red); letter-spacing:.02em;}\n  .amp{margin:2px 0; font-size:15px; font-weight:700; color:var(--red);}\n  .dept{margin:0 0 18px; font-size:17px; font-weight:700; color:var(--red); letter-spacing:.02em;}\n  header hr{border:none; border-top:1.5px solid var(--ink); margin:0;}\n\n  .date{text-align:right; margin:20px 0 26px; font-size:14.5px;}\n\n  .salutation{margin:0 0 22px; font-size:16px; font-weight:600; letter-spacing:.02em;}\n  .dear{margin:0 0 20px;}\n\n  .ref{margin:0 0 18px; font-size:15px; font-weight:700; text-decoration:underline; text-underline-offset:3px;}\n\n  p{margin:0 0 16px; color:var(--ink2); text-align:justify;}\n\n  ul{margin:0 0 18px; padding-left:26px;}\n  li{margin-bottom:9px; color:var(--ink2);}\n  li::marker{color:var(--ink);}\n\n  .sign-block{margin-top:36px;}\n  .sign-img{height:70px; margin-bottom:2px; display:block;}\n  .signer{margin:0; font-weight:600; color:var(--ink);}\n  .title{margin:0; font-weight:700; letter-spacing:.02em; color:var(--ink);}\n\n  footer{margin-top:48px; padding-top:14px; border-top:1.5px solid var(--ink); text-align:center;}\n  footer .h{font-weight:700; font-size:12px; letter-spacing:.03em; color:var(--red); margin:6px 0 3px;}\n  footer p{margin:0 0 2px; font-size:11.5px; color:var(--ink2); text-align:center;}\n  footer a{color:var(--blue); text-decoration:none;}\n  footer a:hover{text-decoration:underline;}\n\n  @media (max-width:640px){\n    .sheet{margin:0; border:none; border-radius:0; padding:32px 22px 36px;}\n    .actions{padding:14px 16px 0;}\n    .date{text-align:left;}\n  }\n\n  @page{ size:letter; margin:11mm 13mm; }\n  @media print{\n    body{background:#fff; font-size:12px; line-height:1.45;}\n    .actions{display:none;}\n    .sheet{margin:0; border:none; box-shadow:none; padding:0; max-width:none; background:#fff;}\n    .crest{width:74px; margin-bottom:6px;}\n    header{padding-bottom:2px;}\n    p{margin:6px 0;}\n    ul{margin:6px 0 6px 0;}\n    li{margin:2px 0;}\n    .sign-img{height:52px;}\n    .sign-block{margin-top:14px; padding-top:0;}\n    footer{margin-top:18px; padding-top:8px; font-size:9.5px; line-height:1.35;}\n    .sheet, header, .sign-block, footer, ul, li{break-inside:avoid;}\n  }\n</style>\n</head>\n<body>\n\n<div class=\"actions\">\n  <a class=\"dl\" href=\"Brian_OAG_Recomendation.pdf\" download=\"Brian_OAG_Recomendation.pdf\">\n    <svg viewBox=\"0 0 24 24\"><path d=\"M12 3v12m0 0l-4-4m4 4l4-4M4 21h16\"/></svg>\n    Download PDF\n  </a>\n</div>\n\n<main class=\"sheet\">\n\n  <header>\n    <img class=\"crest\" alt=\"Coat of arms of Kenya\" src=\"data:image/png;base64,\">\n    <p class=\"republic\">REPUBLIC OF KENYA</p>\n    <p class=\"office\">OFFICE OF THE ATTORNEY GENERAL</p>\n    <p class=\"amp\">&amp;</p>\n    <p class=\"dept\">DEPARTMENT OF JUSTICE</p>\n    <hr>\n  </header>\n\n  <p class=\"date\">11<sup>th</sup> August 2026</p>\n\n  <p class=\"salutation\">TO WHOM IT MAY CONCERN</p>\n\n  <p class=\"dear\">Dear Sir/Madam,</p>\n\n  <p class=\"ref\">REF: RECOMMENDATION LETTER FOR BRIAN MAINA KURIA</p>\n\n  <p>This letter is to confirm that the above-named person was on attachment at the Office of the Attorney General and Department of Justice, ICT Unit from 11<sup>th</sup> May 2026 to 11<sup>th</sup> August 2026.</p>\n\n  <p style=\"margin-bottom:10px;\">His duties included:</p>\n  <ul>\n    <li>Managing the ICT helpdesk</li>\n    <li>Configuration and troubleshooting of the local area network/Internet devices</li>\n    <li>Managing Active Directory user accounts on MS-Windows Server Domain</li>\n    <li>Installing &amp; configuring operating systems, antivirus and other user programs</li>\n    <li>Carrying out preventive maintenance and minor repairs of ICT equipment</li>\n    <li>Configuring, managing and maintenance of printers</li>\n    <li>Data backup and Recovery</li>\n    <li>Digitization and Data entry</li>\n  </ul>\n\n  <p>In the course of his duties, he proved to be obedient, a good team player with excellent communication and interpersonal skills capable of working under minimum supervision.</p>\n\n  <p>We unreservedly recommend him to any future employer.</p>\n\n  <div class=\"sign-block\">\n    <img class=\"sign-img\" alt=\"Signature of Amos Oyoo\" src=\"data:image/png;base64,\">\n    <p class=\"signer\">Amos Oyoo,</p>\n    <p class=\"title\">DIRECTOR, ICT</p>\n  </div>\n\n  <footer>\n    <p class=\"h\">STATE LAW OFFICE,</p>\n    <p><b>SHERIA HOUSE, HARAMBEE AVENUE,</b> P.O Box 40112 - 00100, Nairobi, Kenya. Tel: +254 20 2227461/2251355/0700072929/0732529995</p>\n    <p>E-MAIL: <a href=\"mailto:info@ag.go.ke\">info@ag.go.ke</a> WEBSITE: <a href=\"http://www.statelaw.go.ke\">www.statelaw.go.ke</a></p>\n    <p class=\"h\" style=\"margin-top:10px;\">DEPARTMENT OF JUSTICE</p>\n    <p><b>CO-OPERATIVE BANK HOUSE, HAILE SELASSIE AVENUE</b>, P.O. Box 56057 \u2013 00200, Nairobi, Kenya. TEL: +254 20 2224029/2240337</p>\n    <p>E-MAIL: <a href=\"mailto:legal@justice.go.ke\">legal@justice.go.ke</a> WEBSITE: <a href=\"http://www.statelaw.go.ke\">www.statelaw.go.ke</a></p>\n  </footer>\n\n</main>\n</body>\n</html>\n"
